import{_ as r,a0 as s,w as d,s as i,ao as l,I as a,a1 as n,A as p,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"安卓編年史（9）：安卓 1.6 Donut——CDMA 支持將安卓帶給了各個運營商 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（9）：安卓 1.6 Donut——CDMA 支持將安卓帶給了各個運營商 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（9）：安卓 1.6 Donut——CDMA 支持將安卓帶給了各個運營商 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（9）：安卓 1.6 Donut——CDMA 支持將安卓帶給了各個運營商 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/09 - The history of Android","title":"安卓編年史（9）：安卓 1.6 Donut——CDMA 支持將安卓帶給了各個運營商","tag":"The history of Android","desc":""},"relativePath":"The history of Android/09 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/09 - The history of Android.md"};function u(T,t,h,f,g,A){const e=s("Link");return d(),i("div",null,[t[14]||(t[14]=l('<h1 id="安卓編年史-9-安卓-1-6-donut——cdma-支持將安卓帶給了各個運營商" tabindex="-1">安卓編年史（9）：安卓 1.6 Donut——CDMA 支持將安卓帶給了各個運營商 <a class="header-anchor" href="#安卓編年史-9-安卓-1-6-donut——cdma-支持將安卓帶給了各個運營商" aria-label="Permalink to “安卓編年史（9）：安卓 1.6 Donut——CDMA 支持將安卓帶給了各個運營商”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/marketab2.png" alt="新版安卓市場——黑色比重減少，白色和綠色增多。"></p><p><em>新版安卓市場——黑色比重減少，白色和綠色增多。 [Ron Amadeo 供圖]</em></p><p>###安卓 1.6 Donut——CDMA 支持將安卓帶給了各個運營商###</p><p>安卓的第四個版本——1.6 甜甜圈——在 2009 年 9 月發佈，這時是在紙杯蛋糕面世的 5 個月後。儘管有無數更新，谷歌仍然在給安卓添加基本的功能。甜甜圈帶來了對不同屏幕尺寸和 CDMA 的支持，還有一個文本語音轉換引擎。</p><p>安卓 1.6 是個很好的更新例子，要在今天的話，它將沒什麼理由作為一個獨立更新存在。主要的改進基本上可以總結為新版安卓市場、相機以及 YouTube。從這一年起，像這樣的應用已經從系統分離開來，並且谷歌任何時候都能升級它們。然而在完成所有的這些模組化功能工作之前，看起來甚至是一個微小的應用更新似乎都需要完整的系統更新。</p><p>另一個重大改進——CDMA 支持——也表明了除了版本號之外，谷歌仍然在忙於將基本功能帶到安卓上來。</p><p>安卓市場被標註為版本“1.6”，並且得到了一個徹底的改進。原本的全黑設計被拋棄，轉向帶有綠色高亮的白色應用設計——安卓的設計師很明顯使用了安卓吉祥物來獲得靈感。</p><p>新的市場對谷歌來説一定是個新的應用設計風格。屏幕頂部的五分之一用於顯示橫幅 logo，表明了這個應用確實是“安卓市場”。在橫幅之下是應用、遊戲以及下載按鈕，一個搜索按鈕被安置在橫幅的右側。在導航鍵下面顯示着特色應用的快照，可以在它們之間滑動。再下面是個垂直滾動列表，顯示了更多的特色應用。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/marketpages.png" alt="新的市場設計，展示了：帶有截圖的應用頁面，應用分類頁面，應用榜，下載。"></p><p><em>新的市場設計，展示了：帶有截圖的應用頁面、應用分類頁面、應用排行榜、下載。 [Ron Amadeo 供圖]</em></p><p>市場的最大的新增內容是包含應用截圖。安卓用户終於可以在安裝之前看到應用長什麼樣子——之前他們只能看到簡短的描述和用户評論。你的個人星級評價和評論被放在顯著位置，隨後是描述，最後是截圖。查看截圖常常需要一點點滾動來查看——如果你想要找個設計尚佳的應用，那可要費一番功夫了。</p><p>點擊應用或遊戲按鈕會打開一個分類列表，就像你在上面第二張圖看到的那樣。選擇一個類別之後，更多的導航顯示在了屏幕頂部，用户可以看到“熱門付費”、“熱門免費”，或在分類裏看到各自的“熱門新品”應用。儘管這些看起來像是會加載出新頁面的按鈕，實際上它們僅僅是個笨拙的標籤頁。每個按鈕邊有個綠色小燈指示現在哪個標籤處於活躍狀態。這個界面最讚的地方是應用列表是無窮滾動的（滾動加載）——一旦你到達列表底部的時候，它將加載更多應用。這個特性使得查看應用列表變得輕鬆，但是你點開任意一個應用再返回的話將會丟失你在列表裏的位置——你得從頭開始查看。下載部分可以做一些連新的 Google Play 商店都做不到的事：不過是顯示一個已購買應用列表而已。</p><p>儘管新的市場看起來無疑比舊的好多了，但應用間的一致性更糟糕了。看起來就像是每個應用都是由不同團隊製作的，他們之間從沒溝通過所有的安卓應用應該有的樣子。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/device-2013-12-27-145949.png" alt="相機取景窗，照片回看界面，菜單。"></p><p><em>相機取景窗，照片回看界面，菜單。 [Ron Amadeo 供圖]</em></p><p>舉個例子，相機應用從全屏、精簡設計變成一個盒狀的邊緣帶控制的取景窗。在相機應用中，谷歌着手引入擬物化，將應用包裝成一個大致復刻了皮革紋經典相機的樣子。在相機和攝像機之間切換通過一個缺乏想像力的開關完成，下面是個觸摸快門按鈕。</p><p>點擊最近照片快照不再會打開相冊，而是一個內建在了相機應用內定製的照片查看器。當你查看照片的時候，皮革質感的控制區從相機操作鍵變成圖片操作鍵，你可以在這裏刪除、共享照片，或者把照片設置成壁紙或聯繫人圖像。這裏圖片之間依然沒有滑動操作——切換照片還是要通過照片兩側的箭頭按鈕完成。</p><p>第二張截圖展示的是設計師減少對菜單按鈕依賴的例子之一，因為安卓團隊慢慢開始意識到其在可發現性上的糟糕表現。許多的應用設計者（包括那些在谷歌的）使用菜單作為所有種類的控制和導航元素的集中之處。但大多數用户沒想過點擊菜單按鈕，也從沒看到這些指令。</p><p>未來版本的安卓的公共主題會將選項從菜單移到主要屏幕上，使得整個系統對用户更加友好。菜單按鈕在安卓 4.0 中被完全移除，並且它只在老式應用中被支持。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/settings1.png" alt="電池以及文本語音轉換引擎設置。"></p><p><em>電池以及文本語音轉換引擎設置。 [Ron Amadeo 供圖]</em></p><p>甜甜圈是第一個持續追蹤電池使用量的安卓版本。在“關於手機”菜單裏有個選項“電池使用”，它會以百分比的方式顯示應用以及硬件功能的電池用量。點擊其中一項會打開一個單獨的相關狀態頁面。硬件項目有個按鈕可以直接跳轉到它們的設置界面，所以，舉個例子，如果你覺得顯示的電池用量太高你可以更改顯示的屏幕超時。</p><p>安卓 1.6 同樣是第一個支持文本語音轉換引擎（TTS）的版本，這意味着系統以及應用能夠用機器合成聲音來回應你。“語音合成器”選項允許你設置語言，選擇語速，以及從安卓市場安裝語音數據（慎重）。今天，谷歌在安卓上部署它自己的 TTS 引擎，但是似乎甜甜圈是通過硬編碼的方式使用了來自 SVOX 的 TTS 引擎。但 SVOX 的引擎並未部署在甜甜圈上，所以點擊“安裝語音數據”會鏈接到安卓市場的一個應用。（甜甜圈的全盛期幾年後，這個應用已被撤下。看起來似乎安卓 1.6 再也不能説話了。）</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/grabbag16.png" alt="從左到右：新的小部件，搜索欄界面，新清除通知按鈕，新相冊控件。"></p><p><em>從左到右：新的小部件，搜索欄界面，新清除通知按鈕，新相冊控件。 [Ron Amadeo 供圖]</em></p><p>前端小部件部分花了更多的功夫。甜甜圈帶來了全新的叫做“電量控制”小部件。它包含了常見耗電功能的開關：Wi-Fi、藍牙、GPS、同步（同谷歌服務器之間），以及亮度。</p><p>搜索小部件同樣經過了重新設計，變得更加纖細，並且內置了一個麥克風按鈕用於語音搜索。它現在有了些實質界面並且夠實時搜索，不僅僅是搜索互聯網，還能搜索你的應用和歷史。</p><p>“清除通知”按鈕大幅縮水並且去掉了“通知”字樣。在稍晚些的安卓後續版本總它還會縮減成僅僅是個方形按鈕。相冊繼續遵循了把功能從菜單裏拿出來的趨勢，並且將它們放在用户面前——單張圖片查看界面得到了“設置為”、“分享”以及“刪除”按鈕。</p><hr><p><img src="http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg" alt="Ron Amadeo"></p>',31)),a("p",null,[n(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:p(()=>[...t[0]||(t[0]=[o("Ron Amadeo",-1)])]),_:1}),t[2]||(t[2]=o(" / Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。 ",-1)),n(e,{href:"https://twitter.com/RonAmadeo"},{default:p(()=>[...t[1]||(t[1]=[o("@RonAmadeo",-1)])]),_:1})]),t[15]||(t[15]=a("hr",null,null,-1)),a("p",null,[t[4]||(t[4]=o("via: ",-1)),n(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/9/"},{default:p(()=>[...t[3]||(t[3]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/9/",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=o("譯者：",-1)),n(e,{href:"https://github.com/alim0x"},{default:p(()=>[...t[5]||(t[5]=[o("alim0x",-1)])]),_:1}),t[8]||(t[8]=o(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[6]||(t[6]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[9]||(t[9]=[o("LCTT",-1)])]),_:1}),t[12]||(t[12]=o(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...t[10]||(t[10]=[o("Linux中國",-1)])]),_:1}),t[13]||(t[13]=o(" 榮譽推出",-1))])])}const y=r(m,[["render",u]]);export{x as __pageData,y as default};
